/* stipple-portrait.js — interactive stippled portrait.
 *
 * Usage:
 *   <canvas id="portrait" style="width:420px;aspect-ratio:1"></canvas>
 *   <script src="stipple-portrait.js"></script>
 *   <script>StipplePortrait(document.getElementById('portrait'));</script>
 *
 * Behaviour:
 *   - A fresh random dot layout on every page load, weighted by a density map.
 *   - Dots appear already in place (no entrance animation).
 *   - Dots flee the pointer and spring back (not for visitors with prefers-reduced-motion).
 *   - Dots fade to invisible as time on the site passes (clock shared across pages in one tab via sessionStorage).
 *   - Once faded, the pointer reveals nearby dots, with a short trail.
 *   - Canvas is transparent; it draws only dots. Pauses when off screen or the tab is hidden.
 *
 * No dependencies. Call once per canvas. Returns { destroy() }.
 */
(function (root) {
  'use strict';

  // Greyscale density map, 400x400 PNG: brighter = more dots. Same image as stipple-density.png.
  var DEFAULT_DENSITY = 'data:image/png;base64,';

  var DEFAULTS = {
    density: DEFAULT_DENSITY,   // URL or data URI of the density map (must be same-origin or CORS-enabled)
    count: 16000,               // number of dots
    dot: 0.0013,                // dot radius as a fraction of canvas width
    reach: 0.065,               // pointer repel radius, fraction of width
    reveal: 0.2,                // radius within which the pointer brings faded dots back
    fade: 60,                   // seconds on the site until fully faded; 0 or Infinity disables fading
    ink: '#17171c',             // dot colour
    storageKey: 'stippleSessionStart', // sessionStorage key holding the session start time; null = count from page load
    maxPixelRatio: 2            // cap on devicePixelRatio, for performance
  };

  function StipplePortrait(canvas, options) {
    var o = {}, k;
    for (k in DEFAULTS) o[k] = DEFAULTS[k];
    for (k in (options || {})) o[k] = options[k];

    var ctx = canvas.getContext('2d');
    var n = o.count;
    var hx = new Float32Array(n), hy = new Float32Array(n);   // home positions (0..1)
    var x = new Float32Array(n), y = new Float32Array(n);     // current positions
    var vx = new Float32Array(n), vy = new Float32Array(n);
    var glow = new Float32Array(n);                           // per-dot reveal amount, decays over ~1s

    // Time on site: measured from the first page of this tab's session, so it keeps running on pages without the portrait.
    var start = Date.now();
    if (o.storageKey) {
      try {
        var s = parseInt(sessionStorage.getItem(o.storageKey), 10);
        if (s > 0 && s <= start) start = s; else sessionStorage.setItem(o.storageKey, String(start));
      } catch (e) { /* storage unavailable: fall back to counting from page load */ }
    }

    var W = 0;
    function fit() {
      var r = canvas.getBoundingClientRect(), d = Math.min(root.devicePixelRatio || 1, o.maxPixelRatio);
      W = Math.max(200, Math.round(r.width * d));
      canvas.width = canvas.height = W;
    }
    fit();
    root.addEventListener('resize', fit);

    var p = { x: 0, y: 0, on: false };
    function move(e) {
      var r = canvas.getBoundingClientRect();
      p.x = (e.clientX - r.left) / r.width; p.y = (e.clientY - r.top) / r.height; p.on = true;
    }
    function leave() { p.on = false; }
    function up(e) { if (e.pointerType !== 'mouse') p.on = false; }
    canvas.addEventListener('pointermove', move);
    canvas.addEventListener('pointerdown', move);
    canvas.addEventListener('pointerleave', leave);
    canvas.addEventListener('pointerup', up);

    var visible = true, io = null;
    if ('IntersectionObserver' in root) {
      io = new IntersectionObserver(function (e) { visible = e[0].isIntersecting; });
      io.observe(canvas);
    }

    var LV = 6, bx = [], by = [], cnt = new Int32Array(LV), i;
    for (i = 0; i < LV; i++) { bx.push(new Float32Array(n)); by.push(new Float32Array(n)); }

    // Visitors who ask for reduced motion keep the fade and reveal, but dots do not flee the pointer.
    var still = !!(root.matchMedia && root.matchMedia('(prefers-reduced-motion: reduce)').matches);

    var raf = 0, dead = false;
    var img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function () {
      if (dead) return;
      // Fresh random layout on every load: rejection-sample positions against the density map.
      var S = img.naturalWidth, c = document.createElement('canvas');
      c.width = c.height = S;
      var g = c.getContext('2d', { willReadFrequently: true });
      g.drawImage(img, 0, 0, S, S);
      var d = g.getImageData(0, 0, S, S).data;
      for (var j = 0, guard = 0; j < n && guard < n * 400; guard++) {
        var px = Math.random(), py = Math.random();
        if (Math.random() * 255 < d[((py * S | 0) * S + (px * S | 0)) * 4]) {
          hx[j] = px; hy[j] = py;
          x[j] = px; y[j] = py; j++; // dots start in place: no entrance animation
        }
      }
      raf = requestAnimationFrame(loop);
    };
    img.src = o.density;

    function loop() {
      if (dead) return;
      raf = requestAnimationFrame(loop);
      if (!visible || document.hidden) return;
      var fading = o.fade > 0 && isFinite(o.fade);
      var base = fading ? Math.max(0, 1 - (Date.now() - start) / 1000 / o.fade) : 1;
      var r2 = o.reach * o.reach, v2 = o.reveal * o.reveal, rad = Math.max(0.7, o.dot * W);
      ctx.clearRect(0, 0, W, W);
      ctx.fillStyle = o.ink;
      cnt.fill(0);
      if (base > 0) { ctx.globalAlpha = base; ctx.beginPath(); }
      for (var i = 0; i < n; i++) {
        var ax = (hx[i] - x[i]) * 0.05, ay = (hy[i] - y[i]) * 0.05, tg = 0;
        if (p.on) {
          var dx = x[i] - p.x, dy = y[i] - p.y, d2 = dx * dx + dy * dy;
          if (d2 < r2 && !still) { var d = Math.sqrt(d2) + 1e-5, f = (1 - d / o.reach) * 0.007; ax += dx / d * f; ay += dy / d * f; }
          if (d2 < v2) { var q = 1 - Math.sqrt(d2) / o.reveal; tg = q * q * (3 - 2 * q); }
        }
        vx[i] = (vx[i] + ax) * 0.84; vy[i] = (vy[i] + ay) * 0.84;
        x[i] += vx[i]; y[i] += vy[i];
        var gl = glow[i] = Math.max(tg, glow[i] * 0.965);
        var X = x[i] * W, Y = y[i] * W;
        if (base > 0) { ctx.moveTo(X + rad, Y); ctx.arc(X, Y, rad, 0, 6.2832); }
        if (base < 1 && gl > 0.04) { var k = Math.min(LV - 1, gl * LV | 0); bx[k][cnt[k]] = X; by[k][cnt[k]++] = Y; }
      }
      if (base > 0) ctx.fill();
      // Dots the pointer has passed near, drawn back in over the fading base.
      for (var k2 = 0; k2 < LV; k2++) {
        if (!cnt[k2]) continue;
        ctx.globalAlpha = (1 - base) * Math.min(1, (k2 + 1.6) / LV);
        ctx.beginPath();
        for (var j = 0; j < cnt[k2]; j++) { ctx.moveTo(bx[k2][j] + rad, by[k2][j]); ctx.arc(bx[k2][j], by[k2][j], rad, 0, 6.2832); }
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    return {
      destroy: function () {
        dead = true; cancelAnimationFrame(raf);
        root.removeEventListener('resize', fit);
        canvas.removeEventListener('pointermove', move); canvas.removeEventListener('pointerdown', move);
        canvas.removeEventListener('pointerleave', leave); canvas.removeEventListener('pointerup', up);
        if (io) io.disconnect();
      }
    };
  }

  root.StipplePortrait = StipplePortrait;
})(window);
